  const prot_cipher_str = new lazy.ctypes.char.ptr();
  const prot_is_valid = new lazy.ctypes.bool();

  if (
    RNPLib.rnp_op_verify_get_protection_info(
      verify_op,
      prot_mode_str.address(),
      prot_cipher_str.address(),
      prot_is_valid.address()
